#include "Wavetable.h"
static void testWavetables(const File& root,Assets& assets){
    prepareWavetables();auto* bank=preparedWavetables();expect(bank!=nullptr,"wavetable bank prepares before audio rendering");bool bounded=true;double minimumRms=1;
    for(int table=0;table<wavetableCount;++table)for(int frame=0;frame<wavetableFrames;++frame){double sum=0,power=0;for(int i=0;i<wavetableSize;++i){float v=readWavetable(bank,table,frame/3.,i/(double)wavetableSize,1./65536);bounded&=std::isfinite(v)&&std::abs(v)<=1.000001f;sum+=v;power+=v*v;}expect(std::abs(sum/wavetableSize)<.000001,"every built-in frame has negligible DC offset");minimumRms=jmin(minimumRms,std::sqrt(power/wavetableSize));}
    expect(bounded&&minimumRms>.02,"original wavetable families are finite, audible and peak bounded");
    for(int table=0;table<wavetableCount;++table){double difference=0;for(int i=0;i<73;++i){double phase=i/73.;double a=readWavetable(bank,table,1./3,phase,.002),b=readWavetable(bank,table,2./3,phase,.002),mid=readWavetable(bank,table,.5,phase,.002);expect(std::abs(mid-(a+b)*.5)<.0000001,"frame morphing continuously interpolates neighboring waveforms");difference+=std::abs(readWavetable(bank,table,0,phase,.002)-readWavetable(bank,table,1,phase,.002));}expect(difference>.01,"each table family has distinct morph endpoints");expect(readWavetable(bank,table,.4,-.25,.002)==readWavetable(bank,table,.4,.75,.002),"wavetable phase wraps without a discontinuous edge");}
    bool continuous=true;for(int harmonics:{2,4,8,16,32,64,128})for(int table=0;table<wavetableCount;++table){double step=.45/harmonics;continuous&=std::abs(readWavetable(bank,table,.4,.173,step*(1-1e-8))-readWavetable(bank,table,.4,.173,step*(1+1e-8)))<.000001;}expect(continuous,"harmonic mip transitions are continuous at pitch boundaries");
    juce::dsp::FFT fft(12);std::array<float,8192> data{};for(int table=0;table<wavetableCount;++table){for(int i=0;i<4096;++i)data[(size_t)i]=readWavetable(bank,table,.4,i*1229./4096,1229./4096);std::fill(data.begin()+4096,data.end(),0.f);fft.performFrequencyOnlyForwardTransform(data.data(),true);float wanted=data[1229],unwanted=0;for(int bin=1;bin<=2048;++bin)if(bin!=1229)unwanted=jmax(unwanted,data[(size_t)bin]);expect(wanted>10&&unwanted/wanted<.0001f,"high-pitch mips suppress harmonics above the allowed band instead of folding them back");}
    int cycles=0;float previous=0;for(int i=0;i<48000;++i){float v=readWavetable(bank,0,1,i*440./48000,440./48000);if(previous<=0&&v>0)++cycles;previous=v;}expect(std::abs(cycles-440)<=1,"periodic table lookup preserves A4 tuning");expect(readWavetable(nullptr,0,0,0,.1)==0&&readWavetable(bank,99,0,0,.1)==0&&readWavetable(bank,0,0,0,0)==0&&readWavetable(bank,0,0,0,std::numeric_limits<double>::quiet_NaN())==0,"invalid or unprepared table reads fail safely without allocation");
    SynthVoice voice;bool stable=true;for(double rate:{8000.,22050.,48000.,192000.})for(int pitch:{0,60,127})for(int table=0;table<wavetableCount;++table){SynthPatch p;p.table=table;p.tablePosition=1;p.tableEnv=-1;p.tableLfo=1;p.tableDecay=.01f;p.lfoRate=20;p.lfoPitch=100;p.resonance=1;p.cutoff=20000;p.filterEnv=6;p.noise=.5f;p.sub=1;voice.start(pitch,rate,777);for(int i=0;i<4000;++i){float value=voice.process(p,2,i<2800,.001f,.02f);stable&=std::isfinite(value)&&std::abs(value)<=.56f;}}expect(stable,"extreme pitch, resonance and table sweeps remain finite across rates");
    Track track;track.instrument=Instrument::wavetable;for(int index=20;index<synthParameterCount;++index){auto spec=synthParameterSpecs()[(size_t)index];for(double normal:{0.,.5,1.}){double value=synthParameterFromNormal(index,normal);auto result=setSynthParameter(track,index,value);expect(result.wasOk()&&std::abs(synthParameterNormal(index,synthParameterValue(track,index))-(index==24?std::round(normal*7)/7:index==41?std::round(normal):normal))<.00001,"new synth controls convert physical/normalized values and validate bounds");}}auto oldPatch=track.synth;expect(setSynthParameter(track,20,std::numeric_limits<double>::quiet_NaN()).failed()&&track.synth==oldPatch,"nonfinite morph edits preserve the previous patch");
    auto source=emptyProject();source.bpm=120;source.loop=false;source.patterns[0].length=4;source.patterns[0].lanes[7]={{0,1,60,.8f},{.1,.8,64,.6f},{.2,.7,67,.6f}};auto& instrument=source.tracks[7];instrument.instrument=Instrument::wavetable;instrument.synth=factorySynthPresets()[44].patch;instrument.attack=.005f;instrument.release=.2f;instrument.send=0;auto audio=render(source,assets,root,36000,127),other=render(source,assets,root,36000,733);bool identical=true;for(int ch=0;ch<2;++ch)for(int i=0;i<36000;++i)identical&=audio.getSample(ch,i)==other.getSample(ch,i);expect(identical&&audio.getMagnitude(0,0,36000)>.001,"polyphonic wavetable playback is audible and independent of callback size");
    auto plain=source;plain.tracks[7].synth.tableEnv=plain.tracks[7].synth.tableLfo=0;plain.tracks[7].synth.tablePosition=0;auto a=render(plain,assets,root,24000);plain.tracks[7].synth.tablePosition=1;auto b=render(plain,assets,root,24000);double difference=0;for(int i=0;i<24000;++i)difference+=std::abs(a.getSample(0,i)-b.getSample(0,i));expect(difference>.1,"morph position changes actual generated audio");plain.tracks[7].synth.tableEnv=-1;plain.tracks[7].synth.tableLfo=.5f;b=render(plain,assets,root,24000);difference=0;for(int i=0;i<24000;++i)difference+=std::abs(a.getSample(0,i)-b.getSample(0,i));expect(difference>.1,"table envelope and LFO generate evolving audio");
    auto engine=makeEngine(source,assets,root);engine->stop();for(int i=0;i<128;++i)expect(engine->audition(7,24+i%80,true,.6f,.1f),"bounded wavetable audition queue accepts polyphonic input");AudioBuffer<float> block(2,512);for(int i=0;i<40;++i)engine->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(std::isfinite(block.getMagnitude(0,0,512)),"wavetable voice stealing remains bounded at maximum polyphony");engine->stop();engine->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(block.getMagnitude(0,0,512)==0,"Stop clears wavetable voices and tails");
    auto file=root.getChildFile("wavetable-project.pulse");Project loaded;expect(saveProject(source,file).wasOk()&&loadProject(file,loaded).wasOk()&&JSON::toString(projectToJson(source))==JSON::toString(projectToJson(loaded)),"project schema 13 round-trips complete wavetable state and variable step lengths");
    for(auto key:{"table","tablePosition","tableEnv","tableDecay","tableLfo"}){auto json=projectToJson(source);(*json["tracks"].getArray())[7]["synth"].getDynamicObject()->removeProperty(key);auto before=JSON::toString(projectToJson(loaded));expect(projectFromJson(json,loaded).failed()&&JSON::toString(projectToJson(loaded))==before,"schema 13 rejects incomplete wavetable state atomically");auto bad=synthPatchToJson(instrument.synth);bad.getDynamicObject()->setProperty(key,"invalid");auto patch=instrument.synth;expect(synthPatchFromJson(bad,patch).failed()&&patch==instrument.synth,"wavetable parser rejects wrong field types without mutation");}
    for(double value:{-.001,1.001,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){auto bad=synthPatchToJson(instrument.synth);bad.getDynamicObject()->setProperty("tablePosition",value);auto patch=instrument.synth;expect(synthPatchFromJson(bad,patch).failed()&&patch==instrument.synth,"wavetable positions reject nonfinite and out-of-range doubles");}auto bad=synthPatchToJson(instrument.synth);bad.getDynamicObject()->setProperty("table",2.5);auto patch=instrument.synth;expect(synthPatchFromJson(bad,patch).failed(),"fractional table selection is rejected");auto invalid=source;invalid.tracks[7].synth.table=99;auto hash=SHA256(file).toHexString();expect(saveProject(invalid,file).failed()&&SHA256(file).toHexString()==hash,"invalid table state cannot replace a saved project");auto playback=std::make_unique<Playback>();String warning;expect(compilePlayback(invalid,assets,root,*playback,warning).failed(),"invalid wavetable state cannot reach the audio callback");
    auto legacy=projectToJson(source);legacy.getDynamicObject()->setProperty("schema",12);expect(projectFromJson(legacy,loaded).failed(),"a downgraded schema cannot silently reinterpret a wavetable as FM");
    for(auto kind:{Instrument::analog,Instrument::fm}){auto old=source;old.masterSoftClip=true;old.tracks[7].instrument=kind;old.tracks[7].synth=factorySynthPresets()[kind==Instrument::analog?6:28].patch;auto json=projectToJson(old);json.getDynamicObject()->setProperty("schema",12);for(auto& row:*json["tracks"].getArray())for(auto key:{"table","tablePosition","tableEnv","tableDecay","tableLfo"})row["synth"].getDynamicObject()->removeProperty(key);expect(projectFromJson(json,loaded).wasOk()&&loaded.tracks[7].synth==old.tracks[7].synth,"schema 12 Analog/FM patches gain neutral table defaults");a=render(old,assets,root,24000);b=render(loaded,assets,root,24000);identical=true;for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)identical&=a.getSample(ch,i)==b.getSample(ch,i);expect(identical,"legacy Analog/FM project migration preserves every audio sample");}
    auto sound=factorySynthPresets()[44];auto soundFile=root.getChildFile("wavetable.pulsesound");SynthPreset read;expect(saveSynthPreset(sound,soundFile).wasOk()&&loadSynthPreset(soundFile,read).wasOk()&&read.patch==sound.patch&&read.instrument==Instrument::wavetable,"schema-2 wavetable sound files round-trip with no external assets");auto oldSound=synthPresetToJson(sound);oldSound.getDynamicObject()->setProperty("schema",1);expect(synthPresetFromJson(oldSound,read).failed(),"wavetable sounds require a version understood by their loader");oldSound=synthPresetToJson(factorySynthPresets()[6]);oldSound.getDynamicObject()->setProperty("schema",1);for(auto key:{"table","tablePosition","tableEnv","tableDecay","tableLfo"})oldSound["patch"].getDynamicObject()->removeProperty(key);expect(synthPresetFromJson(oldSound,read).wasOk()&&read.patch==factorySynthPresets()[6].patch,"legacy schema-1 sound files remain readable without table fields");
    auto libraryFile=root.getChildFile("wavetable-library.json");SoundLibrary library;library.personal.push_back({"user-legacy",read});library.favorites.add("user-legacy");auto oldLibrary=soundLibraryToJson(library);oldLibrary.getDynamicObject()->setProperty("schema",1);(*oldLibrary["personal"].getArray())[0].getDynamicObject()->setProperty("sound",oldSound);libraryFile.replaceWithText(JSON::toString(oldLibrary));hash=SHA256(libraryFile).toHexString();expect(loadSoundLibrary(libraryFile,library).wasOk()&&SHA256(libraryFile).toHexString()==hash,"legacy sound libraries load without rewriting user files");expect(putPersonalSound(libraryFile,{"user-table",sound}).wasOk()&&setSoundFavorite(libraryFile,"user-table",true).wasOk()&&loadSoundLibrary(libraryFile,library).wasOk()&&library.personal.size()==2&&library.favorites.contains("user-legacy")&&library.favorites.contains("user-table")&&(int)JSON::parse(libraryFile.loadFileAsString())["schema"]==2,"library schema 2 retains old sounds/favorites while adding wavetable patches");
    ProjectTemplate info;expect(saveProjectTemplate(source,root,root.getChildFile("wavetable-templates"),"Wavetable starter","Embedded morphing sound",TemplateContent::complete,info).wasOk()&&loadProjectTemplate(info,loaded).wasOk()&&loaded.tracks[7].synth==source.tracks[7].synth,"local templates embed complete wavetable sounds");
    RenderSettings settings;settings.bits=32;settings.tailSeconds=0;auto exported=root.getChildFile("wavetable-export.wav");auto result=renderAudio(source,assets,root,exported,settings);AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(exported));AudioBuffer<float> decoded(2,24000);identical=result.wasOk()&&reader;if(identical){reader->read(&decoded,0,24000,0,true,true);for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)identical&=decoded.getSample(ch,i)==audio.getSample(ch,i);}expect(identical&&decoded.getMagnitude(0,0,24000)>.001,"offline float WAV matches callback wavetable audio sample for sample");
}
